Given the code below, put the objects in the order the engine checks them when it looks up `d.toString`.

```js
class Animal {}
class Dog extends Animal {}
const d = new Dog();
d.toString();
```

What does this code log?

```js
const base = { greeting: 'hi' };
const child = Object.create(base);
child.greeting = 'hello';
console.log(base.greeting, child.greeting);
```

What does this code log?

```js
const proto = { inherited: 1 };
const obj = Object.create(proto);
obj.own = 2;
const seen = [];
for (const k in obj) seen.push(k);
console.log(Object.keys(obj), seen);
```

What does this code log?

```js
const a = { x: 1 };
const b = { x: 1 };
const c = a;
console.log(a === b, a === c);
```

What does this code log?

```js
const key = 'color';
const car = { [key]: 'red', key: 'blue' };
console.log(car.color, car.key);
```

What does this code log?

```js
const user = {
  first: 'Ada',
  last: 'Lovelace',
  get full() { return `${this.first} ${this.last}`; },
};
user.first = 'Grace';
console.log(user.full);
```

What does this code log?

```js
class MathUtil {
  static double(n) { return n * 2; }
}
const m = new MathUtil();
console.log(MathUtil.double(2), typeof m.double);
```

What does this code log?

```js
function Box(v) { this.v = v; return { v: 'override' }; }
function Crate(v) { this.v = v; return 42; }
console.log(new Box(1).v, new Crate(2).v);
```

What does this code log?

```js
let reads = 0;
const src = { get n() { reads++; return reads; } };
const copy = Object.assign({}, src);
console.log(copy.n, copy.n, reads);
```

Given this code, which statements are true? (Choose two.)

```js
class Point {
  constructor(x) { this.x = x; }
  norm() { return Math.abs(this.x); }
}
const p = new Point(-3);
const q = { ...p };
```

What does this code log?

```js
const o = { b: 1, 2: 'two', a: 2, 1: 'one', '-1': 'neg' };
console.log(Object.keys(o));
```

What does this code log?

```js
class A {
  greet = () => 'field';
  greet() { return 'method'; }
}
const a = new A();
console.log(a.greet(), A.prototype.greet.call(a));
```

What does this code log?

```js
function F() {}
const f = new F();
F.prototype = {};
console.log(f instanceof F, Object.getPrototypeOf(f) === F.prototype);
```

What does this code log?

```js
'use strict';
const cfg = Object.seal({ mode: 'dev' });
cfg.mode = 'prod';
try {
  cfg.debug = true;
} catch (e) {
  console.log(e.constructor.name);
}
console.log(cfg.mode, 'debug' in cfg);
```

Given this code, which statements are true? (Choose two.)

```js
class Base {
  static create() { return new this(); }
}
class Child extends Base {}
const c = Child.create();
```

What does this code log?

```js
class Base {
  name = 'base';
  constructor() { console.log(this.describe()); }
  describe() { return `Base sees ${this.name}`; }
}
class Derived extends Base {
  name = 'derived';
  describe() { return `Derived sees ${this.name}`; }
}
new Derived();
```

What does this code log?

```js
class A { constructor() { this.x = 1; } }
class B extends A {
  constructor() {
    this.y = 2;
    super();
  }
}
try { new B(); } catch (e) { console.log(e.constructor.name); }
```

What does this code log?

```js
const proto = {
  set value(v) { this._v = v * 2; },
};
const obj = Object.create(proto);
obj.value = 5;
console.log(Object.hasOwn(obj, 'value'), obj._v, obj.value);
```

What does this code log?

```js
'use strict';
const proto = {};
Object.defineProperty(proto, 'id', { value: 1, writable: false });
const obj = Object.create(proto);
try { obj.id = 2; } catch (e) { console.log(e.constructor.name); }
console.log(obj.id, Object.hasOwn(obj, 'id'));
```

What does this code log?

```js
class Account {
  #balance = 0;
  static isAccount(o) { return #balance in o; }
  read(o) { return o.#balance; }
}
const a = new Account();
const fake = { '#balance': 99 };
console.log(Account.isAccount(a), Account.isAccount(fake));
try { a.read(fake); } catch (e) { console.log(e.constructor.name); }
```

What does this code log?

```js
class Stack extends Array {
  peek() { return this[this.length - 1]; }
}
const s = Stack.from([1, 2, 3]);
const doubled = s.map((x) => x * 2);
console.log(doubled instanceof Stack, doubled.peek());
```

Given this code, which statements are true? (Choose two.)

```js
class Counter {
  #n = 0;
  inc() { return ++this.#n; }
}
const c = Object.freeze(new Counter());
```

What does this code log?

```js
const target = {
  set x(v) { console.log('setter', v); },
};
Object.assign(target, { x: 1 });
const spread = { ...target, ...{ x: 2 } };
console.log(spread.x);
```

What does this code log? Type the two numbers separated by a space.

```js
class A {
  static count = 0;
  constructor() { this.constructor.count++; }
}
class B extends A {}
new B();
new B();
new A();
console.log(A.count, B.count);
```

What does this code log?

```js
class Stamper {
  constructor(o) { return o; }
}
class Tag extends Stamper {
  #tag = 'secret';
  static has(o) { return #tag in o; }
}
const plain = {};
new Tag(plain);
console.log(Tag.has(plain), Object.keys(plain).length);
```

What does this code log?

```js
class Base {
  set value(v) { console.log('setter', v); }
}
class Child extends Base {
  value = 42;
}
const c = new Child();
console.log(Object.hasOwn(c, 'value'), c.value);
```

What does this code log?

```js
const base = { who() { return 'base'; } };
const mid = {
  __proto__: base,
  who() { return 'mid>' + super.who(); },
};
const borrowed = {
  __proto__: { who() { return 'other'; } },
  who: mid.who,
};
console.log(borrowed.who());
```

In a sloppy-mode (non-strict, non-module) script, what does this code log?

```js
const proto = { get tag() { return this.name; } };
const a = Object.create(proto, { name: { value: 'a' } });
const b = Object.create(a);
b.name = 'b';
console.log(b.tag);
```

What does this code log?

```js
const dict = Object.create(null);
dict.__proto__ = { hacked: true };
const plain = {};
plain.__proto__ = { hacked: true };
console.log(dict.hacked, plain.hacked, Object.keys(dict));
```

What does this code log?

```js
class A {}
A.prototype.x = 1;
class B extends A {
  m() {
    super.x = 2;
    return [super.x, this.x, Object.hasOwn(this, 'x')];
  }
}
console.log(new B().m());
```

Put the log lines in the order they appear when `new Derived()` runs.

```js
const log = (m) => console.log(m);
class Base {
  a = log('Base field');
  constructor() { log('Base constructor'); }
}
class Derived extends Base {
  b = log('Derived field');
  constructor() {
    log('Derived before super');
    super();
    log('Derived after super');
  }
}
```

What number does this code log?

```js
let n = 0;
const src = { get v() { n++; return n; } };
const viaDescriptors = Object.defineProperties({}, Object.getOwnPropertyDescriptors(src));
viaDescriptors.v;
viaDescriptors.v;
const viaSpread = { ...src };
viaSpread.v;
viaSpread.v;
console.log(n);
```
